BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE owner_id uuid:=gen_random_uuid();reader_id uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();member_id uuid;link_id uuid;hidden_id uuid;r jsonb;s jsonb;page jsonb;first_id uuid;publication jsonb;checked jsonb;
BEGIN
 INSERT INTO auth.users(id) VALUES(owner_id),(reader_id),(outsider);
 INSERT INTO public.user_roles VALUES(owner_id,'admin');
 INSERT INTO public.redirect_workspace_members(user_id,kind,label,role) VALUES(reader_id,'user','Team reader','viewer') RETURNING id INTO member_id;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','team-report-readable','/events') RETURNING id INTO link_id;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','team-report-hidden','/events') RETURNING id INTO hidden_id;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Hidden team report link','none');
 INSERT INTO public.redirect_link_metadata(redirect_key,folder_id) SELECT 'redirects:'||hidden_id,id FROM public.redirect_link_folders WHERE name='Hidden team report link';
 PERFORM public.record_redirect_visit(link_id,'/go/team-report-readable',NULL,NULL,'fixture','CH',NULL,302,NULL,'/events');
 PERFORM public.record_redirect_visit(hidden_id,'/go/team-report-hidden',NULL,NULL,'fixture','CH',NULL,302,NULL,'/events');
 r:=public.redirect_saved_report_resource('create',owner_id,NULL,p_values=>'{"name":"Team campaign","filters":{}}');
 IF r->>'visibility'<>'private' OR r->>'owner_user_id'<>owner_id::text OR r->>'canEdit'<>'true' THEN RAISE EXCEPTION 'Private default/owner metadata changed';END IF;
 BEGIN PERFORM public.redirect_saved_report_resource('get',reader_id,member_id,(r->>'id')::uuid);RAISE EXCEPTION 'Private report discovered';EXCEPTION WHEN no_data_found THEN NULL;END;
 publication:=public.redirect_report_share_resource('create',owner_id,NULL,(r->>'id')::uuid,p_values=>jsonb_build_object('title','Independent public dashboard','reportVersion',r->>'version'));
 s:=public.redirect_saved_report_resource('patch',owner_id,NULL,(r->>'id')::uuid,jsonb_build_object('version',r->>'version','visibility','team'));
 page:=public.redirect_saved_report_resource('list',reader_id,member_id,p_values=>'{"view":"team"}');
 IF page->>'count'<>'1' OR page->>'canPublishToTeam'<>'false' OR page#>>'{data,0,canEdit}'<>'false' OR page#>'{data,0}'?'owner_user_id' THEN RAISE EXCEPTION 'Team discovery permissions/privacy failed';END IF;
 IF public.redirect_saved_report_resource('list',reader_id,member_id)->>'count'<>'0' THEN RAISE EXCEPTION 'Default personal list expanded';END IF;
 IF(public.redirect_saved_report_resource('run',reader_id,member_id,(r->>'id')::uuid)#>>'{totals,clicks}')::int<>1 THEN RAISE EXCEPTION 'Team report run bypassed reader scope';END IF;
 BEGIN PERFORM public.redirect_saved_report_resource('patch',reader_id,member_id,(r->>'id')::uuid,jsonb_build_object('version',s->>'version','name','Hijack'));RAISE EXCEPTION 'Reader edited team report';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_saved_report_resource('delete',reader_id,member_id,(r->>'id')::uuid);RAISE EXCEPTION 'Reader deleted team report';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_report_share_resource('list',reader_id,member_id,(r->>'id')::uuid);RAISE EXCEPTION 'Reader saw public share capabilities';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_saved_report_resource('create',reader_id,member_id,p_values=>'{"name":"Forbidden team","filters":{},"visibility":"team"}');RAISE EXCEPTION 'Member published team report';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 page:=public.redirect_saved_report_resource('create',reader_id,member_id,p_values=>jsonb_build_object('name','Private copy','filters',s->'filters'));
 IF page->>'visibility'<>'private' OR page->>'canEdit'<>'true' THEN RAISE EXCEPTION 'Copy did not stay private';END IF;
 BEGIN PERFORM public.redirect_saved_report_resource('list',outsider,NULL,p_values=>'{"view":"team"}');RAISE EXCEPTION 'Outsider discovered report';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_saved_report_resource('patch',owner_id,NULL,(r->>'id')::uuid,jsonb_build_object('version',r->>'version','visibility','private'));RAISE EXCEPTION 'Stale visibility edit accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_saved_report_resource('list',reader_id,member_id,p_values=>'{"view":null}');RAISE EXCEPTION 'Invalid view accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.redirect_saved_report_resource('patch',owner_id,NULL,(r->>'id')::uuid,jsonb_build_object('version',s->>'version','visibility',true));RAISE EXCEPTION 'Invalid visibility accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.redirect_saved_report_resource('create',owner_id,NULL,p_values=>'{"name":"Second team","filters":{},"visibility":"team"}');
 page:=public.redirect_saved_report_resource('list',reader_id,member_id,p_values=>'{"view":"team"}',p_limit=>1);first_id:=(page#>>'{data,0,id}')::uuid;
 IF page->>'count'<>'2' OR page->>'nextCursor' IS NULL THEN RAISE EXCEPTION 'Team paging/count failed';END IF;
 page:=public.redirect_saved_report_resource('list',reader_id,member_id,p_values=>'{"view":"team"}',p_limit=>1,p_after=>first_id);
 IF page#>>'{data,0,id}'=first_id::text OR page->>'nextCursor' IS NOT NULL THEN RAISE EXCEPTION 'Team cursor repeated row';END IF;
 DELETE FROM public.user_roles WHERE user_id=owner_id;
 IF public.redirect_saved_report_resource('list',reader_id,member_id,p_values=>'{"view":"team"}')->>'count'<>'0' THEN RAISE EXCEPTION 'Lost publisher role still discoverable';END IF;
 BEGIN PERFORM public.redirect_saved_report_resource('get',reader_id,member_id,(r->>'id')::uuid);RAISE EXCEPTION 'Lost publisher report read survived';EXCEPTION WHEN no_data_found THEN NULL;END;
 INSERT INTO public.user_roles VALUES(owner_id,'admin');
 s:=public.redirect_saved_report_resource('patch',owner_id,NULL,(r->>'id')::uuid,jsonb_build_object('version',s->>'version','visibility','private'));
 BEGIN PERFORM public.redirect_saved_report_resource('get',reader_id,member_id,(r->>'id')::uuid);RAISE EXCEPTION 'Made-private report still readable';EXCEPTION WHEN no_data_found THEN NULL;END;
 checked:=public.redirect_public_report_check((publication->>'id')::uuid,repeat('a',64));
 IF checked->>'version' IS NULL THEN RAISE EXCEPTION 'Team visibility changed public publication';END IF;
 UPDATE public.redirect_workspace_members SET active=false WHERE id=member_id;
 BEGIN PERFORM public.redirect_saved_report_resource('list',reader_id,member_id,p_values=>'{"view":"team"}');RAISE EXCEPTION 'Inactive reader discovered team report';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
RESET ROLE;
ROLLBACK;
